#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#if defined(__SSE2__)
#include <emmintrin.h>
#endif
#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <omp.h>

static bool restricted_second_ok(unsigned int restriction, unsigned char byte) {
  switch (restriction) {
    case 1: return byte >= 0xA0;  // E0
    case 2: return byte <= 0x9F;  // ED
    case 3: return byte >= 0x90;  // F0
    case 4: return byte <= 0x8F;  // F4
    default: return true;
  }
}

static bool validate_scalar_tail(const unsigned char *bytes, size_t length,
                                 size_t index, unsigned int pending,
                                 unsigned int restriction) {
  while (index < length) {
    if (pending != 0) {
      const unsigned char byte = bytes[index++];
      if ((byte & 0xC0) != 0x80 || !restricted_second_ok(restriction, byte)) {
        return false;
      }
      --pending;
      restriction = 0;
      continue;
    }

    const unsigned char byte1 = bytes[index++];
    if (byte1 < 0x80) {
      continue;
    }
    if (byte1 < 0xE0) {
      if (byte1 < 0xC2 || index >= length || (bytes[index++] & 0xC0) != 0x80) {
        return false;
      }
      continue;
    }
    if (byte1 < 0xF0) {
      if (index + 1 >= length) {
        return false;
      }
      const unsigned char byte2 = bytes[index++];
      if ((byte2 & 0xC0) != 0x80 ||
          (byte1 == 0xE0 && byte2 < 0xA0) ||
          (byte1 == 0xED && byte2 >= 0xA0) ||
          (bytes[index++] & 0xC0) != 0x80) {
        return false;
      }
      continue;
    }

    if (byte1 > 0xF4 || index + 2 >= length) {
      return false;
    }
    const unsigned char byte2 = bytes[index++];
    if ((byte2 & 0xC0) != 0x80 ||
        (byte1 == 0xF0 && byte2 < 0x90) ||
        (byte1 == 0xF4 && byte2 > 0x8F) ||
        (bytes[index++] & 0xC0) != 0x80 ||
        (bytes[index++] & 0xC0) != 0x80) {
      return false;
    }
  }
  return pending == 0;
}

#if defined(__SSE2__)
static inline __m128i unsigned_ge_u8(__m128i value, unsigned char threshold) {
  const __m128i sign_bit = _mm_set1_epi8(-128);
  const unsigned char previous = static_cast<unsigned char>(threshold - 1u);
  const unsigned char biased_limit = static_cast<unsigned char>(previous ^ 0x80u);
  int signed_limit = static_cast<int>(biased_limit);
  if (signed_limit >= 128) {
    signed_limit -= 256;
  }
  return _mm_cmpgt_epi8(_mm_xor_si128(value, sign_bit),
                        _mm_set1_epi8(static_cast<char>(signed_limit)));
}

static inline __m128i unsigned_le_u8(__m128i value, unsigned char threshold) {
  const __m128i all_ones = _mm_set1_epi8(-1);
  return _mm_xor_si128(unsigned_ge_u8(value,
                                      static_cast<unsigned char>(threshold + 1u)),
                       all_ones);
}

static inline uint32_t byte_mask(__m128i value) {
  return static_cast<uint32_t>(_mm_movemask_epi8(value));
}

static inline unsigned int restriction_from_last_byte(unsigned char byte) {
  switch (byte) {
    case 0xE0: return 1;
    case 0xED: return 2;
    case 0xF0: return 3;
    case 0xF4: return 4;
    default: return 0;
  }
}
#endif

static bool validate_utf8(const char *input, size_t length) {
  const unsigned char *bytes = reinterpret_cast<const unsigned char *>(input);
#if defined(__SSE2__)
  size_t index = 0;
  uint32_t carry = 0;
  unsigned int restriction = 0;

  while (length - index >= 16) {
    const __m128i block = _mm_loadu_si128(
        reinterpret_cast<const __m128i *>(bytes + index));
    const uint32_t high_mask = byte_mask(block);

    if (high_mask == 0 && carry == 0 && restriction == 0) {
      index += 16;
      continue;
    }

    const __m128i continuation_bytes = _mm_and_si128(
        unsigned_ge_u8(block, 0x80), unsigned_le_u8(block, 0xBF));
    const __m128i lead2_bytes = _mm_and_si128(
        unsigned_ge_u8(block, 0xC2), unsigned_le_u8(block, 0xDF));
    const __m128i lead3_bytes = _mm_and_si128(
        unsigned_ge_u8(block, 0xE0), unsigned_le_u8(block, 0xEF));
    const __m128i lead4_bytes = _mm_and_si128(
        unsigned_ge_u8(block, 0xF0), unsigned_le_u8(block, 0xF4));

    const uint32_t continuation_mask = byte_mask(continuation_bytes);
    const uint32_t lead2_mask = byte_mask(lead2_bytes);
    const uint32_t lead3_mask = byte_mask(lead3_bytes);
    const uint32_t lead4_mask = byte_mask(lead4_bytes);
    const uint32_t classified_mask = continuation_mask | lead2_mask |
                                     lead3_mask | lead4_mask;
    if ((high_mask & ~classified_mask) != 0) {
      return false;
    }

    const uint32_t expected_wide =
        ((lead2_mask | lead3_mask | lead4_mask) << 1) |
        ((lead3_mask | lead4_mask) << 2) |
        (lead4_mask << 3);
    const uint32_t expected_here = (expected_wide & 0xFFFFu) | carry;
    if (continuation_mask != expected_here) {
      return false;
    }

    const __m128i low_9f_bytes = _mm_and_si128(
        unsigned_ge_u8(block, 0x80), unsigned_le_u8(block, 0x9F));
    const __m128i low_8f_bytes = _mm_and_si128(
        unsigned_ge_u8(block, 0x80), unsigned_le_u8(block, 0x8F));
    const __m128i ge_a0_bytes = unsigned_ge_u8(block, 0xA0);
    const __m128i ge_90_bytes = unsigned_ge_u8(block, 0x90);
    const uint32_t e0_mask = byte_mask(_mm_cmpeq_epi8(
        block, _mm_set1_epi8(static_cast<char>(0xE0))));
    const uint32_t ed_mask = byte_mask(_mm_cmpeq_epi8(
        block, _mm_set1_epi8(static_cast<char>(0xED))));
    const uint32_t f0_mask = byte_mask(_mm_cmpeq_epi8(
        block, _mm_set1_epi8(static_cast<char>(0xF0))));
    const uint32_t f4_mask = byte_mask(_mm_cmpeq_epi8(
        block, _mm_set1_epi8(static_cast<char>(0xF4))));
    const uint32_t bad_restricted_pair =
        ((e0_mask << 1) & byte_mask(low_9f_bytes)) |
        ((ed_mask << 1) & byte_mask(ge_a0_bytes)) |
        ((f0_mask << 1) & byte_mask(low_8f_bytes)) |
        ((f4_mask << 1) & byte_mask(ge_90_bytes));
    if (bad_restricted_pair != 0) {
      return false;
    }

    if (restriction != 0) {
      const unsigned char first_byte = static_cast<unsigned char>(
          static_cast<uint32_t>(_mm_cvtsi128_si32(block)) & 0xFFu);
      if (!restricted_second_ok(restriction, first_byte)) {
        return false;
      }
    }

    carry = expected_wide >> 16;
    restriction = restriction_from_last_byte(bytes[index + 15]);
    index += 16;
  }

  unsigned int pending = 0;
  for (uint32_t bits = carry; bits != 0; bits >>= 1) {
    ++pending;
  }
  return validate_scalar_tail(bytes, length, index, pending, restriction);
#else
  return validate_scalar_tail(bytes, length, 0, 0, 0);
#endif
}

extern "C" void run(const void *input1, const void *input2, void *output,
                    int n, int parameter, int threads) {
  *(uint32_t *)output = validate_utf8((const char *)input1, n);
}

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <omp.h>
#if defined(__SSE2__)
#include <emmintrin.h>
#endif

static bool validate_utf8_scalar(const unsigned char *bytes, size_t length) {
  for (size_t index = 0; index < length;) {
    unsigned char byte1 = bytes[index++];
    if (byte1 < 0x80) {
      continue;
    }
    if (byte1 < 0xE0) {
      if (byte1 < 0xC2 || index >= length || (bytes[index++] & 0xC0) != 0x80) {
        return false;
      }
    } else if (byte1 < 0xF0) {
      if (length - index < 2) {
        return false;
      }
      unsigned char byte2 = bytes[index++];
      if ((byte2 & 0xC0) != 0x80
          || (byte1 == 0xE0 && byte2 < 0xA0)
          || (byte1 == 0xED && byte2 >= 0xA0)
          || (bytes[index++] & 0xC0) != 0x80) {
        return false;
      }
    } else {
      if (length - index < 3) {
        return false;
      }
      unsigned char byte2 = bytes[index++];
      if ((byte2 & 0xC0) != 0x80
          || byte1 > 0xF4
          || (byte1 == 0xF0 && byte2 < 0x90)
          || (byte1 == 0xF4 && byte2 > 0x8F)
          || (bytes[index++] & 0xC0) != 0x80
          || (bytes[index++] & 0xC0) != 0x80) {
        return false;
      }
    }
  }
  return true;
}

#if defined(__SSE2__)
static bool restricted_pair_ok(unsigned char lead, unsigned char second) {
  if (lead == 0xE0) {
    return second >= 0xA0;
  }
  if (lead == 0xED) {
    return second < 0xA0;
  }
  if (lead == 0xF0) {
    return second >= 0x90;
  }
  if (lead == 0xF4) {
    return second <= 0x8F;
  }
  return true;
}

static bool validate_utf8_sse2(const unsigned char *bytes, size_t length) {
  const uint32_t all_lanes = 0xFFFFU;
  size_t index = 0;
  uint32_t carry = 0;
  unsigned char pending_restriction = 0;
  const __m128i bias = _mm_set1_epi8(static_cast<char>(0x80));

  while (length - index >= 16) {
    if (pending_restriction != 0
        && !restricted_pair_ok(pending_restriction, bytes[index])) {
      return false;
    }
    pending_restriction = 0;

    const __m128i value = _mm_loadu_si128(
        reinterpret_cast<const __m128i *>(bytes + index));
    const uint32_t high = static_cast<uint32_t>(_mm_movemask_epi8(value));
    if (high == 0 && carry == 0) {
      index += 16;
      continue;
    }

    const __m128i transformed = _mm_xor_si128(value, bias);
    const __m128i continuation_bits = _mm_and_si128(
        value, _mm_set1_epi8(static_cast<char>(0xC0)));
    const uint32_t ascii = all_lanes ^ high;
    const uint32_t continuation = static_cast<uint32_t>(_mm_movemask_epi8(
        _mm_cmpeq_epi8(continuation_bits,
                       _mm_set1_epi8(static_cast<char>(0x80)))));
    const uint32_t lead2 = static_cast<uint32_t>(_mm_movemask_epi8(
        _mm_and_si128(
            _mm_cmpgt_epi8(transformed, _mm_set1_epi8(0x41)),
            _mm_cmpgt_epi8(_mm_set1_epi8(0x60), transformed))));
    const uint32_t lead3 = static_cast<uint32_t>(_mm_movemask_epi8(
        _mm_and_si128(
            _mm_cmpgt_epi8(transformed, _mm_set1_epi8(0x5F)),
            _mm_cmpgt_epi8(_mm_set1_epi8(0x70), transformed))));
    const uint32_t lead4 = static_cast<uint32_t>(_mm_movemask_epi8(
        _mm_and_si128(
            _mm_cmpgt_epi8(transformed, _mm_set1_epi8(0x6F)),
            _mm_cmpgt_epi8(_mm_set1_epi8(0x75), transformed))));

    if ((ascii | continuation | lead2 | lead3 | lead4) != all_lanes) {
      return false;
    }

    const uint32_t expected_raw =
        ((lead2 | lead3 | lead4) << 1)
        | ((lead3 | lead4) << 2)
        | (lead4 << 3);
    const uint32_t expected = (expected_raw & all_lanes) | carry;
    if (continuation != expected) {
      return false;
    }

    const __m128i following = _mm_xor_si128(_mm_srli_si128(value, 1), bias);
    const uint32_t e0 = static_cast<uint32_t>(_mm_movemask_epi8(
        _mm_cmpeq_epi8(value, _mm_set1_epi8(static_cast<char>(0xE0)))));
    const uint32_t ed = static_cast<uint32_t>(_mm_movemask_epi8(
        _mm_cmpeq_epi8(value, _mm_set1_epi8(static_cast<char>(0xED)))));
    const uint32_t f0 = static_cast<uint32_t>(_mm_movemask_epi8(
        _mm_cmpeq_epi8(value, _mm_set1_epi8(static_cast<char>(0xF0)))));
    const uint32_t f4 = static_cast<uint32_t>(_mm_movemask_epi8(
        _mm_cmpeq_epi8(value, _mm_set1_epi8(static_cast<char>(0xF4)))));
    const uint32_t e0_ok = static_cast<uint32_t>(_mm_movemask_epi8(
        _mm_cmpgt_epi8(following, _mm_set1_epi8(0x1F))));
    const uint32_t ed_ok = static_cast<uint32_t>(_mm_movemask_epi8(
        _mm_cmpgt_epi8(_mm_set1_epi8(0x20), following)));
    const uint32_t f0_ok = static_cast<uint32_t>(_mm_movemask_epi8(
        _mm_cmpgt_epi8(following, _mm_set1_epi8(0x0F))));
    const uint32_t f4_ok = static_cast<uint32_t>(_mm_movemask_epi8(
        _mm_cmpgt_epi8(_mm_set1_epi8(0x10), following)));
    const uint32_t restricted_bad =
        (e0 & ~e0_ok) | (ed & ~ed_ok) | (f0 & ~f0_ok) | (f4 & ~f4_ok);
    if ((restricted_bad & 0x7FFFU) != 0) {
      return false;
    }

    carry = expected_raw >> 16;
    const unsigned char last = bytes[index + 15];
    if (last == 0xE0 || last == 0xED || last == 0xF0 || last == 0xF4) {
      pending_restriction = last;
    }
    index += 16;
  }

  const size_t remaining = length - index;
  size_t pending_count = 0;
  while (pending_count < 3 && (carry & (1U << pending_count)) != 0) {
    ++pending_count;
  }
  if ((carry >> pending_count) != 0 || remaining < pending_count) {
    return false;
  }
  if (pending_restriction != 0
      && (remaining == 0
          || !restricted_pair_ok(pending_restriction, bytes[index]))) {
    return false;
  }
  for (size_t i = 0; i < pending_count; ++i) {
    if ((bytes[index + i] & 0xC0) != 0x80) {
      return false;
    }
  }
  return validate_utf8_scalar(bytes + index + pending_count,
                               remaining - pending_count);
}
#endif

static bool validate_utf8(const char *b, size_t length) {
  const unsigned char *bytes = reinterpret_cast<const unsigned char *>(b);
#if defined(__SSE2__)
  if (length >= 16) {
    return validate_utf8_sse2(bytes, length);
  }
#endif
  return validate_utf8_scalar(bytes, length);
}

extern "C" void run(const void *input1, const void *input2, void *output,
                     int n, int parameter, int threads) {
  *(uint32_t *)output = validate_utf8((const char *)input1, n);
}
